    Iterator<String> it = expected.keySet().iterator();
    while (it.hasNext()) {
        String url = it.next();
        LOG.fine("url=" + url);
        String[] vals = expected.get(url);
        Inlinks inlinks = reader.getInlinks(new Text(url));
