            links.add(in.getFromUrl());
        }
        for (int i = 0; i < vals.length; i++) {
            LOG.fine(" -> " + vals[i]);
            Assert.assertTrue(links.contains(vals[i]));
        }
    }
    reader.close();
    fs.delete(testDir, true);
}

